<span style={{ fontSize: 29, fontWeight: 700, color: COLORS.white, fontFamily: "Rajdhani, sans-serif" }}>
{value}{unit ? <span style={{ fontSize: 17, fontWeight: 400, opacity: 0.7, marginLeft: 2 }}>{unit}</span> : null}
</span>
