if (code <= 2) return "POLOJ.";
if (code <= 3) return "OBLAC.";
if (code <= 49) return "MLHA";
if (code <= 59) return "MRHOLÍ";
if (code <= 69) return "DÉŠŤ";
if (code <= 79) return "SNÍH";
