const routeMinAlt = alts.length ? Math.round(Math.min(...alts)) : null;
const routeMaxAlt = alts.length ? Math.round(Math.max(...alts)) : null;
const histMinAlts = seg.history.filter(h => h.minAlt != null).map(h => h.minAlt);
const histMaxAlts = seg.history.filter(h => h.maxAlt != null).map(h => h.maxAlt);
const minAlt = routeMinAlt !== null ? routeMinAlt : (histMinAlts.length ? Math.min(...histMinAlts) : null);
